var isValid = function(s) {
    const openingFor = { ')': '(', ']': '[', '}': '{' };
    const stack = [];
    for (const char of s) {
        if (char in openingFor) {
            if (stack.length === 0 || stack.pop() !== openingFor[char]) return false;
        } else {
            stack.push(char);
        }
    }
    return stack.length === 0;
};

